#include <stdio.h>
#include <stdlib.h>

// Process structure
typedef struct {
    int pid;
    int arrival_time;
    int burst_time;
    int priority;
    int completion_time;
    int turnaround_time;
    int waiting_time;
    int response_time;
} Process;

// Function to calculate waiting time
void calculate_waiting_time(Process *processes, int num_processes) {
    for (int i = 0; i < num_processes; i++) {
        processes[i].waiting_time = processes[i].completion_time - processes[i].arrival_time;
    }
}

// Function to calculate turnaround time
void calculate_turnaround_time(Process *processes, int num_processes) {
    for (int i = 0; i < num_processes; i++) {
        processes[i].turnaround_time = processes[i].completion_time - processes[i].arrival_time;
    }
}

// Function to calculate response time
void calculate_response_time(Process *processes, int num_processes) {
    for (int i = 0; i < num_processes; i++) {
        processes[i].response_time = processes[i].arrival_time - processes[i].arrival_time;
    }
}

// Function to calculate average waiting time
double calculate_average_waiting_time(Process *processes, int num_processes) {
    double sum = 0.0;
    for (int i = 0; i < num_processes; i++) {
        sum += processes[i].waiting_time;
    }
    return sum / num_processes;
}

// Function to calculate average turnaround time
double calculate_average_turnaround_time(Process *processes, int num_processes) {
    double sum = 0.0;
    for (int i = 0; i < num_processes; i++) {
        sum += processes[i].turnaround_time;
    }
    return sum / num_processes;
}

// Function to calculate average response time
double calculate_average_response_time(Process *processes, int num_processes) {
    double sum = 0.0;
    for (int i = 0; i < num_processes; i++) {
        sum += processes[i].response_time;
    }
    return sum / num_processes;
}

// Main function
int main() {
    // Initialize the processes
    Process processes[] = {
        {1, 0, 10, 3},
        {2, 1, 5, 2},
        {3, 2, 3, 1},
        {4, 3, 4, 4},
        {5, 4, 7, 3}
    };
    int num_processes = sizeof(processes) / sizeof(Process);

    // Calculate the waiting time, turnaround time, and response time
    calculate_waiting_time(processes, num_processes);
    calculate_turnaround_time(processes, num_processes);
    calculate_response_time(processes, num_processes);

    // Calculate the average waiting time, turnaround time, and response time
    double average_waiting_time = calculate_average_waiting_time(processes, num_processes);
    double average_turnaround_time = calculate_average_turnaround_time(processes, num_processes);
    double average_response_time = calculate_average_response_time(processes, num_processes);

    // Print the results
    printf("Average waiting time: %f\n", average_waiting_time);
    printf("Average turnaround time: %f\n", average_turnaround_time);
    printf("Average response time: %f\n", average_response_time);

    return 0;
}

