#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <math.h>

#define MAX_CHARS 256
#define MAX_LENGTH 4096

typedef struct {
    char *original;
    char *compressed;
    int original_length;
    int compressed_length;
} compression_t;

void initialize_table(int *table, int size) {
    for (int i = 0; i < size; i++) {
        table[i] = 0;
    }
}

int find_index(char *table, int size, char c) {
    if (isupper(c)) {
        return toupper(c) - 'A';
    } else {
        return tolower(c) - 'a';
    }
}

void compress(char *original, char *compressed, int *table, int size) {
    int j = 0;
    for (int i = 0; i < strlen(original); i++) {
        int index = find_index(table, size, original[i]);
        if (index == -1) {
            table[size - 1] = original[i];
            size++;
            compressed[j++] = original[i];
        } else {
            compressed[j++] = (char) (index + 'A');
        }
    }
    compressed[j] = '\0';
}

void decompress(char *compressed, char *original, int *table, int size) {
    int j = 0;
    for (int i = 0; i < strlen(compressed); i++) {
        if (isalpha(compressed[i])) {
            original[j++] = (char) (table[compressed[i] - 'A'] + 'a');
        } else {
            original[j++] = compressed[i];
        }
    }
    original[j] = '\0';
}

int main() {
    char input[MAX_LENGTH] = "The quick brown fox jumps over the lazy dog. ";
    char compressed[MAX_LENGTH] = {0};
    int table[MAX_CHARS] = {0};
    int size = 0;

    initialize_table(table, MAX_CHARS);

    compress(input, compressed, table, &size);

    printf("Original: %s\n", input);
    printf("Compressed: %s\n", compressed);

    char decompressed[MAX_LENGTH] = {0};
    decompress(compressed, decompressed, table, size);

    printf("Decompressed: %s\n", decompressed);

    return 0;
}

