#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define BOARD_SIZE 3
#define PLAYER_X 'X'
#define PLAYER_O 'O'

// Define the tic tac toe board
char board[BOARD_SIZE][BOARD_SIZE] = {
    {'1', '2', '3'},
    {'4', '5', '6'},
    {'7', '8', '9'}
};

// Define the winning conditions
int win_conditions(char player) {
    // Check rows
    for (int i = 0; i < BOARD_SIZE; i++) {
        if (board[0][i] == player && board[1][i] == player && board[2][i] == player) {
            return 1;
        }
    }

    // Check columns
    for (int j = 0; j < BOARD_SIZE; j++) {
        if (board[j][0] == player && board[j][1] == player && board[j][2] == player) {
            return 1;
        }
    }

    // Check diagonals
    if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
        return 1;
    }

    // If all else fails, it's a draw
    return 0;
}

// Play the tic tac toe game
int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Initialize the game board
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            board[i][j] = ' ';
        }
    }

    // Determine the player who goes first
    char player = rand() % 2 == 0 ? PLAYER_X : PLAYER_O;

    // Play the game until one of the players wins or it's a draw
    while (!win_conditions(player) && board[2][2] != ' ') {
        // Get the player's move
        int move = rand() % 9 + 1;

        // If the move is valid, make it
        if (board[move / BOARD_SIZE][move % BOARD_SIZE] == ' ') {
            board[move / BOARD_SIZE][move % BOARD_SIZE] = player;
        }

        // Switch to the next player
        player = (player == PLAYER_X) ? PLAYER_O : PLAYER_X;
    }

    // Print the winner or draw
    if (win_conditions(player) == 1) {
        printf("Congratulations, %c, you won!", player);
    } else if (board[2][2] == ' ') {
        printf("It's a draw!");
    }

    return 0;
}

